#ifndef LRU_H
#define LRU_H

#include <list>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

// Least-recently-used cache: get and put in O(1). The front of `order_` is the most recently used.
class LruCache {
public:
    explicit LruCache(int capacity);
    // The value, or nullptr on a miss. A hit makes the key the most recently used.
    const std::string* get(const std::string& key);
    // Inserts or updates; returns the evicted key, or "" if nothing was evicted.
    std::string put(const std::string& key, const std::string& value);
    // Keys from most to least recently used.
    std::vector<std::string> keys() const;
    int hits() const { return hits_; }
    int misses() const { return misses_; }

private:
    using Entry = std::pair<std::string, std::string>;
    int capacity_;
    int hits_ = 0, misses_ = 0;
    std::list<Entry> order_;
    std::unordered_map<std::string, std::list<Entry>::iterator> where_;
};

#endif

#include "lru.h"

LruCache::LruCache(int capacity) : capacity_(capacity) {}

const std::string* LruCache::get(const std::string& key) {
    misses_++;            // Milestone 1: find the key, move it to the front, count a hit
    return nullptr;
}

std::string LruCache::put(const std::string& key, const std::string& value) {
    return "";            // Milestone 1 and 2: update or insert at the front; evict from the back when full
}

std::vector<std::string> LruCache::keys() const {
    std::vector<std::string> out;
    for (const auto& e : order_) out.push_back(e.first);
    return out;
}

#include <iostream>
#include <sstream>
#include <string>
#include "lru.h"
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    LruCache* cache = nullptr;
    string line;
    while (getline(cin, line)) {
        istringstream in(line);
        string cmd, a, b, extra;
        if (!(in >> cmd)) continue;
        in >> a >> b;
        bool more = static_cast<bool>(in >> extra);
        if (cmd == "CAP" && !cache && !a.empty() && b.empty() && a.find_first_not_of("0123456789") == string::npos && a.size() < 5 && stoi(a) > 0) {
            cache = new LruCache(stoi(a));
            cout << "cache of " << a << "\n";
        } else if (!cache) cout << "error: no cache yet\n";
        else if (cmd == "PUT" && !b.empty() && !more) {
            string ev = cache->put(a, b);
            cout << "stored " << a << (ev.empty() ? "" : ", evicted " + ev) << "\n";
        } else if (cmd == "GET" && !a.empty() && b.empty()) {
            const string* v = cache->get(a);
            cout << (v ? *v : string("miss")) << "\n";
        } else if (cmd == "KEYS" && a.empty()) {
            string all;
            for (const auto& k : cache->keys()) all += (all.empty() ? "" : " ") + k;
            cout << (all.empty() ? "empty" : all) << "\n";
        } else if (cmd == "STATS" && a.empty()) cout << "hits " << cache->hits() << ", misses " << cache->misses() << "\n";
        else cout << "error: bad command " << line << "\n";
    }
    delete cache;
    return 0;
}

