#include "lru.h"

LruCache::LruCache(int capacity) : capacity_(capacity) {}

const std::string* LruCache::get(const std::string& key) {
    auto it = where_.find(key);
    if (it == where_.end()) {
        misses_++;
        return nullptr;
    }
    hits_++;
    order_.splice(order_.begin(), order_, it->second);   // move to front; iterators stay valid
    return &it->second->second;
}

std::string LruCache::put(const std::string& key, const std::string& value) {
    auto it = where_.find(key);
    if (it != where_.end()) {
        it->second->second = value;
        order_.splice(order_.begin(), order_, it->second);
        return "";
    }
    std::string evicted;
    if (static_cast<int>(order_.size()) == capacity_) {
        evicted = order_.back().first;
        where_.erase(evicted);
        order_.pop_back();
    }
    order_.emplace_front(key, value);
    where_[key] = order_.begin();
    return evicted;
}

std::vector<std::string> LruCache::keys() const {
    std::vector<std::string> out;
    for (const auto& e : order_) out.push_back(e.first);
    return out;
}
